package com.example.srchfly;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point for the SRCHFLY Spring Boot application.
 * <p>
 * Migrated from COBOL CICS program SRCHFLY (KERESTES, Sept. 2022).
 * Searches flights according to user-supplied criteria:
 * flight number, departure airport, arrival airport, and/or date.
 * </p>
 */
@SpringBootApplication
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

