package com.example.srchfly.repository;

import com.example.srchfly.model.Flight;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.time.LocalDate;
import java.util.List;

/**
 * Spring Data JPA repository for {@link Flight}.
 * <p>
 * Each query method corresponds to one of the DB2 cursors declared in
 * the original SRCHFLY COBOL program:
 * <ul>
 *   <li>CSR1   – flight date &gt;= today AND flightNum &gt; supplied value</li>
 *   <li>CSR10  – exact flight date</li>
 *   <li>CSR11  – exact flight date AND flight number</li>
 *   <li>CSR100 – exact flight date AND departure airport</li>
 *   <li>CSR1000 – exact flight date AND arrival airport</li>
 *   <li>CSR1100 – exact flight date AND departure airport AND arrival airport</li>
 * </ul>
 * All queries are limited to 10 rows (PERFORM VARYING COUNT2 FROM 1 BY 1
 * UNTIL COUNT2 &gt; 10) via a {@link Pageable} parameter.
 * </p>
 */
@Repository
public interface FlightRepository extends JpaRepository<Flight, String> {

    /**
     * CSR1 – Flights where date &gt;= editDate and flightNum &gt; fnumI.
     * Original: WHERE FLIGHTDATE >= :WS-EDIT-DATE AND FLIGHTNUM > :FNUMI
     */
    @Query("SELECT f FROM Flight f "
         + "WHERE f.flightDate >= :editDate AND f.flightNum > :flightNum "
         + "ORDER BY f.flightDate, f.flightNum")
    List<Flight> findByDateGeAndFlightNumGt(
            @Param("editDate")  LocalDate editDate,
            @Param("flightNum") String    flightNum,
            Pageable pageable);

    /**
     * CSR10 – Flights on an exact date.
     * Original: WHERE FLIGHTDATE = :FDATEI
     */
    @Query("SELECT f FROM Flight f "
         + "WHERE f.flightDate = :flightDate "
         + "ORDER BY f.flightNum")
    List<Flight> findByFlightDate(
            @Param("flightDate") LocalDate flightDate,
            Pageable pageable);

    /**
     * CSR11 – Flight with an exact date and flight number.
     * Original: WHERE FLIGHTDATE = :FDATEI AND FLIGHTNUM = :FNUMI
     */
    @Query("SELECT f FROM Flight f "
         + "WHERE f.flightDate = :flightDate AND f.flightNum = :flightNum "
         + "ORDER BY f.flightNum")
    List<Flight> findByFlightDateAndFlightNum(
            @Param("flightDate") LocalDate flightDate,
            @Param("flightNum") String    flightNum,
            Pageable pageable);

    /**
     * CSR100 – Flights on an exact date from a departure airport.
     * Original: WHERE FLIGHTDATE = :FDATEI AND AIRPORTDEP = :DAIRI
     */
    @Query("SELECT f FROM Flight f "
         + "WHERE f.flightDate = :flightDate AND f.airportDep = :airportDep "
         + "ORDER BY f.flightNum")
    List<Flight> findByFlightDateAndDeparture(
            @Param("flightDate")  LocalDate flightDate,
            @Param("airportDep") String    airportDep,
            Pageable pageable);

    /**
     * CSR1000 – Flights on an exact date to an arrival airport.
     * Original: WHERE FLIGHTDATE = :FDATEI AND AIRPORTARR = :LAIRI
     */
    @Query("SELECT f FROM Flight f "
         + "WHERE f.flightDate = :flightDate AND f.airportArr = :airportArr "
         + "ORDER BY f.flightNum")
    List<Flight> findByFlightDateAndArrival(
            @Param("flightDate")  LocalDate flightDate,
            @Param("airportArr") String    airportArr,
            Pageable pageable);

    /**
     * CSR1100 – Flights on an exact date between specific airports.
     * Original: WHERE FLIGHTDATE = :FDATEI AND AIRPORTDEP = :DAIRI
     *                                      AND AIRPORTARR = :LAIRI
     */
    @Query("SELECT f FROM Flight f "
         + "WHERE f.flightDate = :flightDate "
         + "  AND f.airportDep = :airportDep "
         + "  AND f.airportArr = :airportArr "
         + "ORDER BY f.flightNum")
    List<Flight> findByFlightDateAndDepartureAndArrival(
            @Param("flightDate")  LocalDate flightDate,
            @Param("airportDep") String    airportDep,
            @Param("airportArr") String    airportArr,
            Pageable pageable);
}

