package com.example.srchfly.dto;

/**
 * Inbound DTO representing the search criteria entered by the user.
 * <p>
 * Maps to the CICS map fields:
 * <ul>
 *   <li>FNUMI   – flight number</li>
 *   <li>FDATEI  – flight date (YYYY-MM-DD)</li>
 *   <li>DAIRI   – departure airport (4-char ICAO/IATA code)</li>
 *   <li>LAIRI   – arrival airport (4-char ICAO/IATA code)</li>
 * </ul>
 * All fields are optional; the service layer decides which query to
 * execute based on which combination is provided (mirroring the
 * COBOL COUNT1 accumulation logic).
 * </p>
 *
 * @param flightNum      optional flight number  (FNUMI)
 * @param flightDate     optional date string in YYYY-MM-DD format (FDATEI)
 * @param departureAirport optional departure airport code (DAIRI)
 * @param arrivalAirport   optional arrival airport code (LAIRI)
 */
public record FlightSearchRequest(
        String flightNum,
        String flightDate,
        String departureAirport,
        String arrivalAirport
) {
}

