package com.example.srchfly.dto;

import java.time.LocalDate;

/**
 * Outbound DTO representing a single flight result row.
 * <p>
 * Mirrors the WS-TABLE working-storage group and the per-row map
 * output fields (FLIID0O … FLIID9O, etc.) in SRCHFLY.
 * </p>
 *
 * @param flightNum    flight number  (WS-FLYNUM / FLIIDxO)
 * @param flightDate   flight date    (WS-FLYDT  / FLIDTxO)
 * @param depTime      departure time (WS-FLYTD  / FLITDxO)
 * @param arrTime      arrival time   (WS-FLYTL  / FLITLxO)
 * @param airportDep   departure airport (WS-FLYDE / FLIDExO)
 * @param airportArr   arrival airport   (WS-FLYLD / FLILDxO)
 * @param totPass      total passengers  (WS-FLYPL / FLIPLxO)
 */
public record FlightDto(
        String     flightNum,
        LocalDate  flightDate,
        String     depTime,
        String     arrTime,
        String     airportDep,
        String     airportArr,
        Integer    totPass
) {
