package com.example.srchfly.dto;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.List;

/**
 * Outbound DTO wrapping the flight search results together with
 * meta-information that was displayed on the CICS map.
 * <p>
 * The original CICS map displayed up to 10 flight rows (FLIID0O…FLIID9O),
 * a message line (MSG1O / MSG2O), current date (LDATEO), and current
 * time (LHOURO).  This record carries all that information.
 * </p>
 *
 * @param message      MSG1O equivalent – informational/error text
 * @param currentDate  LDATEO equivalent – server date (DD/MM/YYYY)
 * @param currentTime  LHOURO equivalent – server time (HH:MM:SS)
 * @param flights      up to 10 flight result rows
 */
public record FlightSearchResponse(
        String         message,
        String         currentDate,
        String         currentTime,
        List<FlightDto> flights
) {
}

