package com.example.srchfly.service;

import org.springframework.stereotype.Service;

/**
 * Reproduces the 0800-VERIFY-DATE paragraph from SRCHFLY.
 * <p>
 * The COBOL logic checks:
 * <ol>
 *   <li>Characters 1-4 are numeric (year).</li>
 *   <li>Characters 6-7 are numeric (month).</li>
 *   <li>Characters 9-10 are numeric (day).</li>
 *   <li>Character 5 is '-'.</li>
 *   <li>Character 8 is '-'.</li>
 * </ol>
 * If any check fails the paragraph sets WS-FLAG-DATE = 'N'.
 * Here we return {@code false} in that case.
 * </p>
 */
@Service
public class DateValidationService {

    /**
     * Validates that the supplied date string conforms to YYYY-MM-DD.
     *
     * @param date the raw date string supplied by the user
     * @return {@code true} when format is valid, {@code false} otherwise
     */
    public boolean isValidDateFormat(String date) {
        if (date == null || date.length() != 10) {
            return false;
        }

        // Positions are 0-based in Java; COBOL uses 1-based offsets.
        // FDATEI(1:4) = year  → date[0..3]
        // FDATEI(5:1) = dash1 → date[4]
        // FDATEI(6:2) = month → date[5..6]
        // FDATEI(7:1) = dash2 → date[7]   (note: COBOL says (7:1) which is 7th char)
        // FDATEI(9:2) = day   → date[8..9]

        String year  = date.substring(0, 4);
        char   dash1 = date.charAt(4);
        String month = date.substring(5, 7);
        char   dash2 = date.charAt(7);
        String day   = date.substring(8, 10);

        if (!isNumeric(year) || !isNumeric(month) || !isNumeric(day)) {
            return false;
        }

        if (dash1 != '-' || dash2 != '-') {
            return false;
        }

        return true;
    }

    // ------------------------------------------------------------------
    // Private helpers
    // ------------------------------------------------------------------

    private boolean isNumeric(String s) {
        if (s == null || s.isEmpty()) {
            return false;
        }
        for (char c : s.toCharArray()) {
            if (!Character.isDigit(c)) {
                return false;
            }
        }
        return true;
    }
}

// === FILE: src/main/java/com/example/srchfly/service/FlightSearchService.java ===
package com.example.srchfly.service;

import com.example.srchfly.dto.FlightDto;
import com.example.srchfly.dto.FlightSearchRequest;
import com.example.srchfly.dto.FlightSearchResponse;
import com.example.srchfly.model.Flight;
import com.example.srchfly.repository.FlightRepository;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;

/**
 * Service layer that reproduces all COBOL SRCHFLY business logic.
 *
 * <h2>Paragraph mapping</h2>
 * <table border="1">
 *   <tr><th>COBOL paragraph</th><th>Java method</th></tr>
 *   <tr><td>MAIN-PARA</td><td>{@link #searchFlights(FlightSearchRequest)}</td></tr>
 *   <tr><td>0610-GET-INFORMATION</td><td>{@link #determineSearchCode(FlightSearchRequest)}</td></tr>
 *   <tr><td>0620-SELECT-DB2INFO</td><td>{@link #selectDb2Info(int, FlightSearchRequest)}</td></tr>
 *   <tr><td>0621-SQL-FNUM</td><td>{@link #sqlFnum(String)}</td></tr>
 *   <tr><td>0622-SQL-FDATE</td><td>{@link #sqlFdate(LocalDate)}</td></tr>
 *   <tr><td>0623-SQL-FNUM-FDATE</td><td>{@link #sqlFnumFdate(String, LocalDate)}</td></tr>
 *   <tr><td>0624-SQL-DAIR</td><td>{@link #sqlDair(LocalDate, String)}</td></tr>
 *   <tr><td>0625-SQL-LAIR</td><td>{@link #sqlLair(LocalDate, String)}</td></tr>
 *   <tr><td>0626-SQL-LAIR-DAIR</td><td>{@link #sqlLairDair(LocalDate, String, String)}</td></tr>
 *   <tr><td>0700-SQL-ERROR</td><td>handled via GlobalExceptionHandler</td></tr>
 *   <tr><td>0800-VERIFY-DATE</td><td>{@link DateValidationService#isValidDateFormat(String)}</td></tr>
 * </table>
 *
 * <h2>COUNT1 accumulation (0610-GET-INFORMATION)</h2>
 * <pre>
 *   FNUMI present            → +1
 *   FDATEI present &amp; valid   → +10
 *   DAIRI present (no date)  → +100
 *   LAIRI present (no date)  → +1000
 * </pre>
 */
@Service
@Transactional(readOnly = true)
public class FlightSearchService {

    /** Maximum rows returned by any cursor – mirrors PERFORM … UNTIL COUNT2 &gt; 10. */
    private static final int MAX_RESULTS = 10;

    private static final String DATE_PLACEHOLDER = "YYYY-MM-DD";
    private static final DateTimeFormatter ISO_DATE = DateTimeFormatter.ISO_LOCAL_DATE;

    private final FlightRepository     flightRepository;
    private final DateValidationService dateValidationService;

    public FlightSearchService(FlightRepository flightRepository,
                               DateValidationService dateValidationService) {
        this.flightRepository     = flightRepository;
        this.dateValidationService = dateValidationService;
    }

    // ------------------------------------------------------------------
    // Public API
    // ------------------------------------------------------------------

    /**
     * Entry point – mirrors the MAIN-PARA / 0600-PROCESS-RESEARCH flow.
     *
     * @param request user-supplied search criteria
     * @return response containing up to 10 matching flights plus
     *         informational messages and the current server time
     */
    public FlightSearchResponse searchFlights(FlightSearchRequest request) {

        String currentDate = buildCurrentDate();
        String currentTime = buildCurrentTime();

        // 0610-GET-INFORMATION – determine which combination of criteria
        // the user supplied and calculate the search code.
        int searchCode = determineSearchCode(request);

        // 0620-SELECT-DB2INFO
        SearchResult result = selectDb2Info(searchCode, request);

        return new FlightSearchResponse(
                result.message(),
                currentDate,
                currentTime,
                result.flights()
        );
    }

    // ------------------------------------------------------------------
    // 0610-GET-INFORMATION
    // ------------------------------------------------------------------

    /**
     * Reproduces the COUNT1 accumulation logic from paragraph
     * 0610-GET-INFORMATION.
     *
     * <p>The COBOL code adds:
     * <ul>
     *   <li>1    when FNUMI is not spaces</li>
     *   <li>10   when FDATEI is not spaces and not the placeholder</li>
     *   <li>100  when DAIRI(2:1) is not space AND bit-4 of COUNT1 = 0
     *            (meaning no DATE digit is already counted at the hundreds
     *            position – effectively: departure airport without date
     *            already counted)</li>
     *   <li>1000 when LAIRI(2:1) is not space AND same guard</li>
     * </ul>
     * The guard {@code COUNT1(4:1) = ZERO} in COBOL refers to the
     * 4th character of a PIC 9(4) display field, which is the ones digit
     * (thousands: pos-1, hundreds: pos-2, tens: pos-3, ones: pos-4).
     * At the time the departure-airport check is made COUNT1 can only be
     * 0 or 1 (just flightNum); COUNT1(4:1)=ZERO means ones digit is zero,
     * i.e. COUNT1 is 0. So the airport additions only happen when no date
     * has been detected yet AND COUNT1 is 0 (no flightNum either) –
     * effectively a standalone airport search uses the current date as
     * the implicit date (the COBOL does MOVE WS-EDIT-DATE TO FDATE).
     * We replicate this faithfully.
     * </p>
     *
     * @param request the raw request object
     * @return the numeric search-selector code
     */
    int determineSearchCode(FlightSearchRequest request) {
        int count1 = 0;

        // +1 if flight number provided
        if (isPresent(request.flightNum())) {
            count1 += 1;
        }

        // +10 if date provided and not the placeholder string
        if (isPresent(request.flightDate())
                && !DATE_PLACEHOLDER.equalsIgnoreCase(request.flightDate())) {
            count1 += 10;
        }

        // +100 if departure airport provided AND ones-digit of count1 is 0
        // (COBOL: DAIRI(2:1) NOT = SPACE AND COUNT1(4:1) = ZERO)
        // The DAIRI(2:1) check means the 2nd character of the 4-char field
        // is non-space, effectively meaning a non-trivial code was entered.
        if (isSecondCharPresent(request.departureAirport()) && (count1 % 10 == 0)) {
            count1 += 100;
        }

        // +1000 if arrival airport provided AND same guard
        if (isSecondCharPresent(request.arrivalAirport()) && (count1 % 10 == 0)) {
            count1 += 1000;
        }

        return count1;
    }

    // ------------------------------------------------------------------
    // 0620-SELECT-DB2INFO
    // ------------------------------------------------------------------

    /**
     * Dispatches to the appropriate SQL helper based on {@code searchCode}.
     * Mirrors the EVALUATE COUNT1 block in paragraph 0620-SELECT-DB2INFO.
     *
     * @param searchCode the code produced by {@link #determineSearchCode}
     * @param request    the original request (for raw field values)
     * @return a {@link SearchResult} holding the message and flight list
     */
    SearchResult selectDb2Info(int searchCode, FlightSearchRequest request) {

        return switch (searchCode) {

            // WHEN 1 → flight number only (uses current date as lower bound)
            case 1 -> {
                List<Flight> flights = sqlFnum(request.flightNum());
                yield new SearchResult("", toDto(flights));
            }

            // WHEN 10 → date only
            case 10 -> {
                String dateValidMsg = validateDate(request.flightDate());
                if (!dateValidMsg.isEmpty()) {
                    yield new SearchResult(dateValidMsg, List.of());
                }
                LocalDate date = parseDate(request.flightDate());
                yield new SearchResult("", toDto(sqlFdate(date)));
            }

            // WHEN 11 → flight number AND date
            case 11 -> {
                String dateValidMsg = validateDate(request.flightDate());
                if (!dateValidMsg.isEmpty()) {
                    yield new SearchResult(dateValidMsg, List.of());
                }
                LocalDate date = parseDate(request.flightDate());
                yield new SearchResult("", toDto(sqlFnumFdate(request.flightNum(), date)));
            }

            // WHEN 100 → departure airport only (implicit today)
            case 100 -> {
                LocalDate date = LocalDate.now();
                yield new SearchResult("", toDto(sqlDair(date, request.departureAirport())));
            }

            // WHEN 110 → date AND departure airport
            case 110 -> {
                String dateValidMsg = validateDate(request.flightDate());
                if (!dateValidMsg.isEmpty()) {
                    yield new SearchResult(dateValidMsg, List.of());
                }
                LocalDate date = parseDate(request.flightDate());
                yield new SearchResult("", toDto(sqlDair(date, request.departureAirport())));
            }

            // WHEN 1000 → arrival airport only (implicit today)
            case 1000 -> {
                LocalDate date = LocalDate.now();
                yield new SearchResult("", toDto(sqlLair(date, request.arrivalAirport())));
            }

            // WHEN 1010 → date AND arrival airport
            case 1010 -> {
                String dateValidMsg = validateDate(request.flightDate());
                if (!dateValidMsg.isEmpty()) {
                    yield new SearchResult(dateValidMsg, List.of());
                }
                LocalDate date = parseDate(request.flightDate());
                yield new SearchResult("", toDto(sqlLair(date, request.arrivalAirport())));
            }

            // WHEN 1100 → departure AND arrival airport (implicit today)
            case 1100 -> {
                LocalDate date = LocalDate.now();
                yield new SearchResult("",
                        toDto(sqlLairDair(date, request.departureAirport(),
                                          request.arrivalAirport())));
            }

            // WHEN 1110 → date AND departure AND arrival airport
            case 1110 -> {
                String dateValidMsg = validateDate(request.flightDate());
                if (!dateValidMsg.isEmpty()) {
                    yield new SearchResult(dateValidMsg, List.of());
                }
                LocalDate date = parseDate(request.flightDate());
                yield new SearchResult("",
                        toDto(sqlLairDair(date, request.departureAirport(),
                                          request.arrivalAirport())));
            }

            // WHEN 0 → no data
            case 0 -> new SearchResult("NO DATA INSERT, TRY AGAIN", List.of());

            default  -> new SearchResult("UNKNOWN SEARCH COMBINATION", List.of());
        };
    }

    // ------------------------------------------------------------------
    // Individual SQL helpers (0621 … 0626)
    // ------------------------------------------------------------------

    /**
     * 0621-SQL-FNUM – CSR1.
     * WHERE FLIGHTDATE >= today AND FLIGHTNUM > flightNum (alphabetically).
     *
     * @param flightNum the user-supplied flight number
     * @return up to 10 matching flights
     */
    List<Flight> sqlFnum(String flightNum) {
        LocalDate today = LocalDate.now();
        return flightRepository.findByDateGeAndFlightNumGt(
                today,
                flightNum.trim(),
                PageRequest.of(0, MAX_RESULTS));
    }

    /**
     * 0622-SQL-FDATE – CSR10.
     * WHERE FLIGHTDATE = flightDate.
     *
     * @param flightDate the parsed flight date
     * @return up to 10 matching flights
     */
    List<Flight> sqlFdate(LocalDate flightDate) {
        return flightRepository.findByFlightDate(
                flightDate,
                PageRequest.of(0, MAX_RESULTS));
    }

    /**
     * 0623-SQL-FNUM-FDATE – CSR11.
     * WHERE FLIGHTDATE = flightDate AND FLIGHTNUM = flightNum.
     *
     * @param flightNum  the user-supplied flight number
     * @param flightDate the parsed flight date
     * @return up to 10 matching flights
     */
    List<Flight> sqlFnumFdate(String flightNum, LocalDate flightDate) {
        return flightRepository.findByFlightDateAndFlightNum(
                flightDate,
                flightNum.trim(),
                PageRequest.of(0, MAX_RESULTS));
    }

    /**
     * 0624-SQL-DAIR – CSR100.
     * WHERE FLIGHTDATE = flightDate AND AIRPORTDEP = departureAirport.
     *
     * @param flightDate       the flight date (explicit or implicit today)
     * @param departureAirport ICAO/IATA departure airport code
     * @return up to 10 matching flights
     */
    List<Flight> sqlDair(LocalDate flightDate, String departureAirport) {
        return flightRepository.findByFlightDateAndDeparture(
                flightDate,
                departureAirport.trim(),
                PageRequest.of(0, MAX_RESULTS));
    }

    /**
     * 0625-SQL-LAIR – CSR1000.
     * WHERE FLIGHTDATE = flightDate AND AIRPORTARR = arrivalAirport.
     *
     * @param flightDate     the flight date (explicit or implicit today)
     * @param arrivalAirport ICAO/IATA arrival airport code
     * @return up to 10 matching flights
     */
    List<Flight> sqlLair(LocalDate flightDate, String arrivalAirport) {
        return flightRepository.findByFlightDateAndArrival(
                flightDate,
                arrivalAirport.trim(),
                PageRequest.of(0, MAX_RESULTS));
    }

    /**
     * 0626-SQL-LAIR-DAIR – CSR1100.
     * WHERE FLIGHTDATE = flightDate
     *   AND AIRPORTDEP = departureAirport
     *   AND AIRPORTARR = arrivalAirport.
     *
     * @param flightDate       the flight date (explicit or implicit today)
     * @param departureAirport ICAO/IATA departure airport code
     * @param arrivalAirport   ICAO/IATA arrival airport code
     * @return up to 10 matching flights
     */
    List<Flight> sqlLairDair(LocalDate flightDate,
                              String departureAirport,
                              String arrivalAirport) {
        return flightRepository.findByFlightDateAndDepartureAndArrival(
                flightDate,
                departureAirport.trim(),
                arrivalAirport.trim(),
                PageRequest.of(0, MAX_RESULTS));
    }

    // ------------------------------------------------------------------
    // 0800-VERIFY-DATE delegation
    // ------------------------------------------------------------------

    /**
     * Returns an error message string when the date is invalid,
     * or an empty string when it is valid.
     * Mirrors 0800-VERIFY-DATE setting WS-FLAG-DATE = 'N' and moving
     * the error text to MSG1O.
     *
     * @param dateStr the raw date string
     * @return error message or empty string
     */
    private String validateDate(String dateStr) {
        if (!dateValidationService.isValidDateFormat(dateStr)) {
            return "WRONG DATE FORMAT, TRY TO INSERT DATE AS YYYY-MM-DD";
        }
        return "";
    }

    // ------------------------------------------------------------------
    // 0630-MOVE-INFO equivalent – entity → DTO conversion
    // ------------------------------------------------------------------

    /**
     * Converts a list of {@link Flight} entities to {@link FlightDto} records.
     * Mirrors the 0630-MOVE-INFO paragraph which moves WS-TABLE fields
     * into the CICS map output fields (FLIID0O … FLIID9O, etc.).
     *
     * @param flights list of at most 10 flights from the repository
     * @return ordered list of flight DTOs
     */
    private List<FlightDto> toDto(List<Flight> flights) {
        List<FlightDto> result = new ArrayList<>(flights.size());
        for (Flight f : flights) {
            result.add(new FlightDto(
                    f.getFlightNum(),
                    f.getFlightDate(),
                    f.getDepTime(),
                    f.getArrTime(),
                    f.getAirportDep(),
                    f.getAirportArr(),
                    f.getTotPass()
            ));
        }
        return result;
    }

    // ------------------------------------------------------------------
    // 0200-GET-TIME / 0210-GIVING-TIME equivalents
    // ------------------------------------------------------------------

    /**
     * Builds the display date string in DD/MM/YYYY format.
     * Mirrors WS-EDIT-DATE2 (format 2-DAYS/2-MONTH/2-YEAR) shown as LDATEO.
     *
     * @return formatted date string
     */
    private String buildCurrentDate() {
        LocalDate today = LocalDate.now();
        return String.format("%02d/%02d/%04d",
                today.getDayOfMonth(),
                today.getMonthValue(),
                today.getYear());
    }

    /**
     * Builds the display time string in HH:MM:SS format.
     * Mirrors WS-EDIT-HOUR (H-HOUR:H-MIN:H-SEC) shown as LHOURO.
     *
     * @return formatted time string
     */
    private String buildCurrentTime() {
        java.time.LocalTime now = java.time.LocalTime.now();
        return String.format("%02d:%02d:%02d",
                now.getHour(),
                now.getMinute(),
                now.getSecond());
    }

    // ------------------------------------------------------------------
    // Private utility helpers
    // ------------------------------------------------------------------

    /**
     * Returns {@code true} when {@code value} is non-null, non-empty,
     * and non-blank (i.e. not all spaces). Mirrors COBOL NOT = SPACE.
     */
    private boolean isPresent(String value) {
        return value != null && !value.isBlank();
    }

    /**
     * Checks whether the second character (index 1) of the airport code
     * is non-space. Mirrors COBOL DAIRI(2:1) NOT = SPACE.
     *
     * @param airportCode a 4-character airport code; may be null or short
     * @return {@code true} when second character is a non-space character
     */
    private boolean isSecondCharPresent(String airportCode) {
        if (airportCode == null || airportCode.length() < 2) {
            return false;
        }
        return airportCode.charAt(1) != ' ';
    }

    /**
     * Parses an already-validated ISO date string.
     *
     * @param dateStr a valid YYYY-MM-DD string
     * @return the corresponding {@link LocalDate}
     */
    private LocalDate parseDate(String dateStr) {
        try {
            return LocalDate.parse(dateStr.trim(), ISO_DATE);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException(
                    "Date parsing failed for: " + dateStr, e);
        }
    }

    // ------------------------------------------------------------------
    // Internal result carrier
    // ------------------------------------------------------------------

    /**
     * Internal record used to carry both a message and the flight list
     * out of the switch expression in {@link #selectDb2Info}.
     */
    record SearchResult(String message, List<FlightDto> flights) {
    }
}

