package com.example.srchfly.controller;

import com.example.srchfly.dto.FlightSearchRequest;
import com.example.srchfly.dto.FlightSearchResponse;
import com.example.srchfly.service.FlightSearchService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST controller exposing the flight-search functionality of SRCHFLY.
 *
 * <h2>Endpoint mapping</h2>
 * <pre>
 * GET /api/flights/search
 *   ?flightNum=&lt;value&gt;         (optional – FNUMI)
 *   &amp;flightDate=&lt;YYYY-MM-DD&gt;   (optional – FDATEI)
 *   &amp;departureAirport=&lt;code&gt;  (optional – DAIRI)
 *   &amp;arrivalAirport=&lt;code&gt;    (optional – LAIRI)
 * </pre>
 *
 * <p>
 * The pseudo-conversation CICS flow (SEND MAP / RECEIVE MAP / RETURN TRANSID)
 * is replaced by a stateless HTTP GET.  The map's initial display message
 * "INSERT THE DATA TO DO A RESEARCH" is returned when no parameters are
 * supplied at all.
 * </p>
 */
@RestController
@RequestMapping("/api/flights")
public class FlightSearchController {

    private final FlightSearchService flightSearchService;

    public FlightSearchController(FlightSearchService flightSearchService) {
        this.flightSearchService = flightSearchService;
    }

    /**
     * Searches for available flights matching the supplied criteria.
     * Mirrors the complete MAIN-PARA → 0600-PROCESS-RESEARCH flow.
     *
     * @param flightNum        optional flight number  (FNUMI)
     * @param flightDate       optional date in YYYY-MM-DD (FDATEI)
     * @param departureAirport optional ICAO/IATA departure code (DAIRI)
     * @param arrivalAirport   optional ICAO/IATA arrival code (LAIRI)
     * @return {@code 200 OK} with a {@link FlightSearchResponse} body
     */
    @GetMapping("/search")
    public ResponseEntity<FlightSearchResponse> searchFlights(
            @RequestParam(required = false) String flightNum,
            @RequestParam(required = false) String flightDate,
            @RequestParam(required = false) String departureAirport,
            @RequestParam(required = false) String arrivalAirport) {

        // When no parameters at all → mirror the EIBCALEN = 0 branch which
        // displays 'INSERT THE DATA TO DO A RESEARCH'
        boolean noParams = isBlank(flightNum)
                        && isBlank(flightDate)
                        && isBlank(departureAirport)
                        && isBlank(arrivalAirport);

        if (noParams) {
            FlightSearchResponse initial = new FlightSearchResponse(
                    "INSERT THE DATA TO DO A RESEARCH",
                    buildCurrentDate(),
                    buildCurrentTime(),
                    java.util.List.of());
            return ResponseEntity.ok(initial);
        }

        FlightSearchRequest req = new FlightSearchRequest(
                flightNum,
                flightDate,
                departureAirport,
                arrivalAirport);

        FlightSearchResponse response = flightSearchService.searchFlights(req);
        return ResponseEntity.ok(response);
    }

    // ------------------------------------------------------------------
    // Private helpers (mirroring 0200-GET-TIME / 0210-GIVING-TIME)
    // ------------------------------------------------------------------

    private String buildCurrentDate() {
        java.time.LocalDate today = java.time.LocalDate.now();
        return String.format("%02d/%02d/%04d",
                today.getDayOfMonth(), today.getMonthValue(), today.getYear());
    }

    private String buildCurrentTime() {
        java.time.LocalTime now = java.time.LocalTime.now();
        return String.format("%02d:%02d:%02d",
                now.getHour(), now.getMinute(), now.getSecond());
    }

    private boolean isBlank(String s) {
        return s == null || s.isBlank();
    }
}

