package com.example.srchfly.config;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataAccessException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;

import java.net.URI;
import java.time.Instant;

/**
 * Global exception handler – corresponds to the 0700-SQL-ERROR paragraph
 * and any other unhandled CICS ABEND conditions in the original COBOL.
 *
 * <p>Produces RFC 7807 Problem Details responses.</p>
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    /**
     * Handles database / JPA errors.
     * Mirrors paragraph 0700-SQL-ERROR:
     * "DB2 ERROR, CALL THE IT DEPARTMENT" + SQLCODE + SQLSTATE.
     */
    @ExceptionHandler(DataAccessException.class)
    public ResponseEntity<ProblemDetail> handleDataAccessException(DataAccessException ex) {
        log.error("DB2/JPA error – 0700-SQL-ERROR equivalent", ex);
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.INTERNAL_SERVER_ERROR);
        pd.setType(URI.create("urn:srchfly:error:db-error"));
        pd.setTitle("DB ERROR, CALL THE IT DEPARTMENT");
        pd.setDetail(ex.getMessage());
        pd.setProperty("timestamp", Instant.now());
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(pd);
    }

    /**
     * Handles invalid argument / date-format errors.
     * Mirrors the 0800-VERIFY-DATE 'N' flag path when the date cannot
     * be parsed even after format validation.
     */
    @ExceptionHandler(IllegalArgumentException.class)
    public ResponseEntity<ProblemDetail> handleIllegalArgument(IllegalArgumentException ex) {
        log.warn("Validation / argument error", ex);
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);
        pd.setType(URI.create("urn:srchfly:error:invalid-argument"));
        pd.setTitle("WRONG DATE FORMAT, TRY TO INSERT DATE AS YYYY-MM-DD");
        pd.setDetail(ex.getMessage());
        pd.setProperty("timestamp", Instant.now());
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(pd);
    }

    /**
     * Handles type-mismatch on request parameters.
     */
    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
    public ResponseEntity<ProblemDetail> handleTypeMismatch(
            MethodArgumentTypeMismatchException ex) {
        log.warn("Request parameter type mismatch", ex);
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);
        pd.setType(URI.create("urn:srchfly:error:type-mismatch"));
        pd.setTitle("Invalid request parameter");
        pd.setDetail("Parameter '" + ex.getName() + "' has an invalid value.");
        pd.setProperty("timestamp", Instant.now());
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(pd);
    }

    /**
     * Catch-all handler.
     */
    @ExceptionHandler(Exception.class)
    public ResponseEntity<ProblemDetail> handleAll(Exception ex) {
        log.error("Unexpected error", ex);
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.INTERNAL_SERVER_ERROR);
        pd.setType(URI.create("urn:srchfly:error:unexpected"));
        pd.setTitle("An unexpected error occurred");
        pd.setDetail(ex.getMessage());
        pd.setProperty("timestamp", Instant.now());
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(pd);
    }
}
